/* Generated by Trae Work */
/* 考前资料页渲染：按课程分组展示 HEUOpenResource/heu-icicles 拉取的资料 */
"use strict";
(function () {
  const EXT_MAP = {
    pdf: { label: "PDF", icon: "📕" },
    doc: { label: "Word", icon: "📄" },
    docx: { label: "Word", icon: "📄" },
    md: { label: "Markdown", icon: "📝" }
  };
  function fmtSize(n) {
    if (n >= 1048576) return (n / 1048576).toFixed(1) + " MB";
    if (n >= 1024) return (n / 1024).toFixed(0) + " KB";
    return n + " B";
  }
  function localUrl(group, fileName) {
    return "materials/" + encodeURIComponent(group.dir) + "/" + encodeURIComponent(fileName);
  }
  function blobUrl(repoPath) {
    return MATERIALS_SOURCE.repo_url + "/blob/main/" + repoPath.split("/").map(encodeURIComponent).join("/");
  }

  document.addEventListener("DOMContentLoaded", () => {
    const root = document.getElementById("materials-root");
    const fi = document.getElementById("mat-filter");
    const total = MATERIALS.reduce((a, g) => a + g.items.length, 0);
    const totalBytes = MATERIALS.reduce((a, g) => a + g.items.reduce((x, it) => x + it.size, 0), 0);
    document.getElementById("mat-summary").textContent =
      `共 ${MATERIALS.length} 个课程组 · ${total} 份文件 · ${fmtSize(totalBytes)}`;

    function render() {
      const kw = (fi.value || "").trim().toLowerCase();
      root.innerHTML = "";
      MATERIALS.forEach(g => {
        const items = g.items.filter(it => !kw || it.name.toLowerCase().includes(kw));
        if (kw && items.length === 0) return;
        const bytes = items.reduce((a, it) => a + it.size, 0);
        const sec = h("section", { class: "mat-group" });
        const head = g.track === "zikao"
          ? `<span class="badge zikao">自考 ${g.id}</span>`
          : `<span class="badge code">哈工程课程</span>`;
        const courseLink = g.track === "zikao"
          ? `<a href="zikao.html#course-${g.id}" class="badge ok" style="text-decoration:none;">课程知识点 →</a>`
          : "";
        sec.innerHTML = `
          <h2 class="mat-gtitle">${g.name} ${head} ${courseLink}</h2>
          <p class="muted">${g.note}</p>
          <p class="muted mat-origin">GitHub 来源：<a href="${blobUrl(g.origin)}" target="_blank" rel="noopener">${MATERIALS_SOURCE.repo} / ${g.origin}</a> · 仓库目录 <code>${g.origin}</code> · 本组 ${items.length} 份 · ${fmtSize(bytes)}</p>
          <div class="grid grid-2">${items.map(it => {
            const ext = it.name.split(".").pop().toLowerCase();
            const t = EXT_MAP[ext] || { label: ext.toUpperCase(), icon: "📦" };
            return `
            <div class="card mat-card">
              <div class="mat-head">
                <span class="mat-icon">${t.icon}</span>
                <span class="badge code">${t.label}</span>
                <span class="muted mat-size">${fmtSize(it.size)}</span>
              </div>
              <div class="mat-name">${it.name}</div>
              <div class="mat-actions">
                <a class="btn small" href="${localUrl(g, it.name)}" target="_blank" rel="noopener">打开</a>
                <a class="btn small ghost" href="${blobUrl(it.path)}" target="_blank" rel="noopener">GitHub</a>
              </div>
            </div>`;
          }).join("")}</div>`;
        root.appendChild(sec);
      });
      if (kw && !root.children.length) {
        root.innerHTML = `<div class="notice empty">没有匹配“${fi.value}”的资料，换个关键词试试。</div>`;
      }
    }
    fi.addEventListener("input", render);
    render();
  });
})();
